/usr/bin/bash -lc "PYTHONPATH=source python - <<'PY'
from unittest.mock import patch
import numpy as np
import qcelemental as qcel
import qcengine as qcng

def block(label, matrix, projected=False):
    lines = [label]
    for i, row in enumerate(matrix, 1):
        for chunk, start in enumerate(range(0, len(row), 5), 1):
            values = \" \".join(f\"{x:.10E}\" for x in row[start:start + 5])
            lines.append(f\"{i:6d} {chunk:2d} {values}\")
    if projected:
        lines += [\""'$hessian (projected)", "     1  1   1.0000000000"]
    return "'"\\n\".join(lines + [\""'$end"])

harness = qcng.get_program('"'turbomole', check=False)
for natom, source_name in [(1, 'nprhessian'), (2, 'hessian'), (4, 'both')]:
    dim = 3*natom
    raw=np.arange(1,dim*dim+1,dtype=float).reshape(dim,dim)/1000
    expected=(raw+raw.T)/2
    geom=np.column_stack((np.arange(natom),np.zeros(natom),np.zeros(natom))).ravel()
    mol=qcel.models.Molecule(symbols=['H']*natom,geometry=geom,fix_com=True,fix_orientation=True,validate=False)
    inp=qcel.models.AtomicInput(molecule=mol,driver='hessian',model={'method':'hf','basis':'sto-3g'})
    out={'stdout':' total energy = -1.0000000000\\n'}
    if source_name in ('nprhessian','both'): out['nprhessian']=block('"'$nprhessian'"',expected)
    if source_name in ('hessian','both'): out['hessian']=block('"'$hessian'"',expected,True)
    with patch.object(type(harness),'get_version',return_value='offline-test'):
      result=harness.parse_output(out,inp)
    returned=np.asarray(result.return_result); prop=np.asarray(result.properties.return_hessian); serialized=np.asarray(result.dict()['return_result'])
    print(natom,source_name,returned.shape,prop.shape,serialized.shape,result.properties.calcinfo_natom,np.max(np.abs(returned-expected)),np.allclose(returned, expected, rtol=0, atol=1e-12),np.array_equal(prop,returned),np.array_equal(serialized,returned))
